    date: 'Mar 15, 2026',
    readTime: '8 min read',
    image: 'https://images.unsplash.com/photo-1492619375914-88005aa9e8fb?auto=format&fit=crop&w=1200&q=80',
    author: 'Ulisses Balbino',
    featured: false
